use vm_rust::player::{testing::{TestPlayer,run_test},testing_shared::TestHarness,reserve_player_ref};
use vm_rust::player::allocator::ScriptInstanceAllocatorTrait;
fn main(){let args:Vec<_>=std::env::args().collect();run_test(async{let mut harness=TestPlayer::new();harness.load_movie(&args[1]).await;harness.init_movie().await;harness.eval(&format!("go({})",args[2])).await.unwrap();reserve_player_ref(|p|{println!("frame {} script {:?}",p.movie.current_frame,p.movie.score.get_script_in_frame(p.movie.current_frame).map(|s|(s.cast_lib,s.cast_member)));for c in p.movie.score.channels.iter(){let s=&c.sprite;if let Some(m)=s.member.as_ref(){let cm=p.movie.cast_manager.find_member_by_ref(m);let scripts:Vec<_>=s.script_instance_list.iter().map(|i|{let i=p.allocator.get_script_instance(i);format!("{:?}",i.script)}).collect();println!("sprite{} member{:?} scripts{:?} scriptid{:?} rect{:?}",s.number,m,scripts,cm.and_then(|m|m.get_script_id()),vm_rust::player::score::get_concrete_sprite_rect(p,s));}}});});}
